function readAtlas() {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const table = new Uint8Array(128);
  for (let i = 0; i < alphabet.length; i++) table[alphabet.charCodeAt(i)] = i;
  const end = atlasPayload.indexOf("=");
  const digits = end < 0 ? atlasPayload.length : end;
  const packed = new Uint8Array(Math.floor(digits * 6 / 8));
  let accumulator = 0, bits = 0, write = 0;
  for (let i = 0; i < digits; i++) {
    accumulator = (accumulator << 6) | table[atlasPayload.charCodeAt(i)];
    bits += 6;
    if (bits >= 8) { bits -= 8; packed[write++] = (accumulator >> bits) & 255; }
  }
  const raw = new Uint8Array(560 * 800);
  let src = 0, dst = 0;
  function length(n) {
    if (n === 15) {
      let extra;
      do {
        if (src >= packed.length) throw Error("Incomplete device star texture");
        extra = packed[src++];
        n += extra;
      } while (extra === 255);
    }
    return n;
  }
  while (src < packed.length) {
    const token = packed[src++], literals = length(token >> 4);
    if (src + literals > packed.length || dst + literals > raw.length) throw Error("Invalid star literals");
    raw.set(packed.subarray(src, src + literals), dst);
    src += literals;
    dst += literals;
    if (src === packed.length) break;
    const back = packed[src++] | (packed[src++] << 8);
    const count = 4 + length(token & 15);
    if (back < 1 || back > dst || dst + count > raw.length) throw Error("Invalid star texture reference");
    for (let j = 0; j < count; j++, dst++) raw[dst] = raw[dst - back];
  }
  if (dst !== raw.length) throw Error("Incomplete star texture");
  return raw;
}

